import pandas as pd

# Get S5 climate data to understand the regime pattern
s5_clim = tables['climate'][tables['climate']['avail_season'] == 5].sort_values('avail_doy')
print("=== S5 CLIMATE (Last Season, for regime context) ===")
for idx_id in ['oni', 'pdo']:
    data = s5_clim[s5_clim['index_id'] == idx_id].sort_values('avail_doy')
    if len(data) > 0:
        print(f"\n{idx_id.upper()}:")
        for idx, row in data.iterrows():
            print(f"  DOY {row['avail_doy']}: {row['value']:.2f}")

